class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is ColorMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    } else if (value is TopicMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    } else if (value is AppearanceMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is ModuleMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is SelfCheckMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is ConfigureRequest) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is OfferProductMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is OfferSlotMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is StoreOfferMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is OfferRequestMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is EntitlementMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is PersonMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is ProblemMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is MomentResultMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is StateMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is LogEntryMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is LookTopicMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is LookMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is TeamActionMessage) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is PendingPhotoMessage) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is PendingMessageMessage) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    } else if (value is TimelineItemMessage) {
      buffer.putUint8(150);
      writeValue(buffer, value.encode());
    } else if (value is ConversationMessage) {
      buffer.putUint8(151);
      writeValue(buffer, value.encode());
    } else if (value is AppScreenMessage) {
      buffer.putUint8(152);
      writeValue(buffer, value.encode());
    } else if (value is LinkScreenMessage) {
      buffer.putUint8(153);
      writeValue(buffer, value.encode());
    } else if (value is EventMessage) {
      buffer.putUint8(154);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return ColorMessage.decode(readValue(buffer)!);
      case 130:
        return TopicMessage.decode(readValue(buffer)!);
      case 131:
        return AppearanceMessage.decode(readValue(buffer)!);
      case 132:
        return ModuleMessage.decode(readValue(buffer)!);
      case 133:
        return SelfCheckMessage.decode(readValue(buffer)!);
      case 134:
        return ConfigureRequest.decode(readValue(buffer)!);
      case 135:
        return OfferProductMessage.decode(readValue(buffer)!);
      case 136:
        return OfferSlotMessage.decode(readValue(buffer)!);
      case 137:
        return StoreOfferMessage.decode(readValue(buffer)!);
      case 138:
        return OfferRequestMessage.decode(readValue(buffer)!);
      case 139:
        return EntitlementMessage.decode(readValue(buffer)!);
      case 140:
        return PersonMessage.decode(readValue(buffer)!);
      case 141:
        return ProblemMessage.decode(readValue(buffer)!);
      case 142:
        return MomentResultMessage.decode(readValue(buffer)!);
      case 143:
        return StateMessage.decode(readValue(buffer)!);
      case 144:
        return LogEntryMessage.decode(readValue(buffer)!);
      case 145:
        return LookTopicMessage.decode(readValue(buffer)!);
      case 146:
        return LookMessage.decode(readValue(buffer)!);
      case 147:
        return TeamActionMessage.decode(readValue(buffer)!);
      case 148:
        return PendingPhotoMessage.decode(readValue(buffer)!);
      case 149:
        return PendingMessageMessage.decode(readValue(buffer)!);
      case 150:
        return TimelineItemMessage.decode(readValue(buffer)!);
      case 151:
        return ConversationMessage.decode(readValue(buffer)!);
      case 152:
